def lateWindowAverage {ι : Type} (E : Real → ι → Real) (mu T : Real) : ι → Real :=
  fun i => ((1 - mu) * T)⁻¹ * ∫ t in mu * T..T, E t i

/-- The total of a finite collection of modal weights. -/

def totalWeight {ι : Type} [Fintype ι] (w : ι → Real) : Real :=
  ∑ i, w i

/-- Weights normalized by their total. -/

def normalizedWeights {ι : Type} [Fintype ι] (w : ι → Real) : ι → Real :=
  fun i => w i / totalWeight w

/-- Uniform weights on a finite mode set. -/

def uniformWeights {ι : Type} [Fintype ι] : ι → Real :=
  fun _ => ((Fintype.card ι : Real))⁻¹

/-- The finite `ℓ¹` distance between two weight functions. -/

def l1Distance {ι : Type} [Fintype ι] (w u : ι → Real) : Real :=
  ∑ i, |w i - u i|

/-- Approximate equipartition on a positive late window. -/

def spectralEntropy {ι : Type} [Fintype ι] (w : ι → Real) : Real :=
  ∑ i, Real.negMulLog (w i)

/-- The entropy deficit from the uniform finite distribution. -/

def entropyDeficit {ι : Type} [Fintype ι] (w : ι → Real) : Real :=
  Real.log (Fintype.card ι) - spectralEntropy w

/-- The entropy-derived effective number of occupied modes. -/

def participationNumber {ι : Type} [Fintype ι] (w : ι → Real) : Real :=
  Real.exp (spectralEntropy w)

/-- The late-window average of a pointwise nonnegative energy is nonnegative. -/

def effectiveCoupling (lambda epsilon : Real) (n : Nat) : Real :=
  lambda * Real.rpow epsilon (((n : Real) - 2) / 2)

/-- The finite periodic-chain Hamiltonian with degree-`n` nearest-neighbour interaction. -/

def differenceMatrix {N : Nat} : Matrix (Lattice.Site N) (Lattice.Site N) Real :=
  fun i j => (if j = i + 1 then 1 else 0) - (if j = i then 1 else 0)

/-- The matrix realization of the periodic forward difference. -/

def modalEnergy : Real → Real → Real → Real :=
  fun omegaSq a v => (v ^ 2 + omegaSq * a ^ 2) / 2

/-- A differentiable real harmonic mode conserves its modal energy. -/

def hittingTimes (A : ENNReal → Prop) : Set ENNReal :=
  {t | 0 < t ∧ A t}

/-- The first strictly positive event time, with `⊤` for an empty event set. -/

def firstHittingTime (A : ENNReal → Prop) : ENNReal :=
  sInf (hittingTimes A)

/-- The event holds continuously from `t` through the duration `L`. -/

def PersistsFor (A : ENNReal → Prop) (t L : ENNReal) : Prop :=
  ∀ s, t ≤ s → s ≤ t + L → A s

/-- Strictly positive start times at which the event persists for `L`. -/

def persistenceTimes (A : ENNReal → Prop) (L : ENNReal) : Set ENNReal :=
  {u | 0 < u ∧ PersistsFor A u L}

/-- The first strictly positive start time at which the event persists for `L`. -/

def persistenceTime (A : ENNReal → Prop) (L : ENNReal) : ENNReal :=
  sInf (persistenceTimes A L)

/-- An event that never holds has first hitting time `⊤`. -/

def firstStateHittingTime {X : Type} (P : X → Prop) (D : Real → X) : ENNReal :=
  HittingTime.firstHittingTime (fun t => P (D t.toReal))

/-- The state-event hitting time is the infimum of its strictly positive event times. -/

def forwardDifference {N : Nat} (q : Configuration N) : Configuration N :=
  fun i => q (i + 1) - q i

/-- Pointwise expansion of the periodic forward difference. -/

def massAction {N : Nat} (m : PositiveMassConfig N) (p : Configuration N) :
    Configuration N := fun i => m.mass i * p i

/-- Pointwise multiplication by the inverse mass profile. -/

def inverseMassAction {N : Nat} (m : PositiveMassConfig N) (p : Configuration N) :
    Configuration N := fun i => (m.mass i)⁻¹ * p i

/-- Pointwise multiplication by the square root of the mass profile. -/

def sqrtMassAction {N : Nat} (m : PositiveMassConfig N) (p : Configuration N) :
    Configuration N := fun i => Real.sqrt (m.mass i) * p i

/-- Pointwise multiplication by the inverse square root of the mass profile. -/

def inverseSqrtMassAction {N : Nat} (m : PositiveMassConfig N) (p : Configuration N) :
    Configuration N := fun i => (Real.sqrt (m.mass i))⁻¹ * p i

/-- The finite kinetic energy `∑ᵢ pᵢ²/(2mᵢ)`. -/

def interactionPotential (n : Nat) (lambda x : Real) : Real :=
  x ^ 2 / 2 + (lambda / (n : Real)) * x ^ n

/-- The derivative formula `x + λ xⁿ⁻¹` for a nonzero degree `n`. -/

def interactionForce (n : Nat) (lambda x : Real) : Real :=
  x + lambda * x ^ (n - 1)

/-- The periodic nearest-neighbour force acting on every lattice site. -/

def totalMomentum {N : Nat} [NeZero N] (z : PhaseSpace N) : Real :=
  ∑ i, z.2 i

/-- Pointwise expansion of the outgoing-minus-incoming nearest-neighbour force. -/
